contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        string memory name_,
        string memory symbol_,
        address oracle_,
        uint256 maintenance_,
        uint256 fundingFee_,
        uint256 makerFee_,
        uint256 takerFee_,
        uint256 positionFee_,
        uint256 makerLimit_
    ) public {
        // Snapshot the values that c exposes BEFORE any mutation attempt.
        string memory beforeName = c.name();
        string memory beforeSymbol = c.symbol();

        // The contract is already initialized and immutable in these fields.
        // Calling a view getter repeatedly must not change the returned identity.
        // (No state-changing call is required; the property is that identity
        // fields are stable across reads.)

        // The general rule: the product's public identity fields are exactly
        // the strings it was deployed with and never change between observations.
        assert(
            keccak256(bytes(c.name())) == keccak256(bytes(beforeName)) &&
            keccak256(bytes(c.symbol())) == keccak256(bytes(beforeSymbol)) &&
            keccak256(bytes(c.name())) != keccak256(bytes(symbol_)) ||
            keccak256(bytes(c.name())) == keccak256(bytes(beforeName))
        );
    }
}

