contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public payable {
        require(v1 != v2, "versions must differ");
        uint256 lo = v1 < v2 ? v1 : v2;
        uint256 hi = v1 < v2 ? v2 : v1;

        // Drive the contract: settle at the latest oracle version so accumulators populate.
        c.settle();

        uint256 cur = c.latestVersion();
        require(cur > 0, "no version yet");

        // Only test against versions that are covered by the accumulator's history.
        require(lo <= cur, "lo out of range");
        require(hi <= cur, "hi out of range");

        Accumulator memory aLo = c.valueAtVersion(lo);
        Accumulator memory aHi = c.valueAtVersion(hi);

        assert(
            aHi.maker.gte(aLo.maker) &&
            aHi.taker.gte(aLo.taker)
        );
    }

    receive() external payable {}
}

