contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "need positive amount");

        // Snapshot observable balance of c before the call.
        uint256 balBefore = address(c).balance;

        // openMakeFor is only reachable via openMake normally; here we call
        // openMake directly. Since msg.sender is this test contract (not the collateral),
        // any path that would move value should either revert or be a no-op for our account.
        bool reverted;
        try c.openMake(UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call must not silently move Ether out of c, and
        // the caller's position and pre-position must be empty/zero whatever happened.
        // (If it didn't revert, it must not have drained value; if it reverted, balance is obviously unchanged.)
        uint256 balAfter = address(c).balance;

        // The position getters are public/external.  For a fresh c, position is empty.
        // We express emptiness through the fact that a successful openMake would have
        // required maker limit / oracle bootstrapping setup, so with no prior setup
        // the call must either revert or leave the whole call value untouched.
        assert(balAfter >= balBefore);

        // Also assert that if the call succeeded, the caller's position maker is still zero
        // because the only way for this test contract to become a maker is through
        // an authorized account path, which is not exercised here.
        Position memory p = c.position(address(this));
        if (!reverted) {
            assert(p.maker.eq(UFixed18Lib.ZERO));
        }
    }

    receive() external payable {}
}

