        bool doubleSidedAfterFirst = !posAfterFirst.maker.isZero() && !posAfterFirst.taker.isZero();

        // Second open attempt with a different amount parameter.
        uint256 secondRaw = takeAmount + 1;
        UFixed18 secondAmount = UFixed18.wrap(secondRaw);
        bool secondReverted;
        try c.openTakeFor(account, secondAmount) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        Position memory posAfterSecond = c.position(account);
        bool doubleSidedAfterSecond = !posAfterSecond.maker.isZero() && !posAfterSecond.taker.isZero();
        bool liquidatableAfterSecond = c.isLiquidating(account);

        // General rule: if the first open succeeded and the second open also succeeded,
        // the account must not be left double-sided (the openTakeFor path enforces
        // positionInvariant(account)), and it must not be in liquidation.
        if (firstOk && !secondReverted) {
            assert(!doubleSidedAfterSecond && !liquidatableAfterSecond);
        } else {
            // If either call reverted, the position must still be non-double-sided
            // as an invariant of the reachable state, and liquidation flag must stay false.
            assert(!doubleSidedAfterFirst || !doubleSidedAfterSecond ? true : (!doubleSidedAfterSecond && !liquidatableAfterSecond));
        }
    }

    receive() external payable {}
}

